// ~/temporal-lab/test/hello.test.ts (part 1): one time-skipping server for the file
import { after, before, test } from "node:test";
import assert from "node:assert/strict";
import { fileURLToPath } from "node:url";
import { TestWorkflowEnvironment } from "@temporalio/testing";
import { Worker } from "@temporalio/worker";
import { approve, hello } from "../src/workflows.js";

let env: TestWorkflowEnvironment;
before(async () => { env = await TestWorkflowEnvironment.createTimeSkipping(); });
after(async () => { await env?.teardown(); });

const workflowsPath = fileURLToPath(new URL("../src/workflows.ts", import.meta.url));
const greet = async (name: string) => `Hi ${name} (mock)`; // a mocked activity: a plain function

// ~/temporal-lab/test/hello.test.ts (part 2)
test("parks after a day with no approval", async () => {
  const worker = await Worker.create({ connection: env.nativeConnection, taskQueue: "t", workflowsPath, activities: { greet } });
  const result = await worker.runUntil(
    env.client.workflow.execute(hello, { taskQueue: "t", workflowId: "t-1", args: ["Sean"] }));
  assert.equal(result, "parked"); // a whole day passed in about a second
});

test("approval runs the activity", async () => {
  const worker = await Worker.create({ connection: env.nativeConnection, taskQueue: "t", workflowsPath, activities: { greet } });
  const result = await worker.runUntil(async () => {
    const h = await env.client.workflow.start(hello, { taskQueue: "t", workflowId: "t-2", args: ["Sean"] });
    await h.signal(approve, "dana");
    return h.result();
  });
  assert.equal(result, "Hi Sean (mock) (approved by dana)");
});

// ai-agents/orchestrator/test/ticket-to-pr.test.ts (sketch): a plan waits a day, is reminded once, then approved
test("a plan not approved for a day gets one reminder", async () => {
  const notes: string[] = [];
  const activities = { ...happyPath, notify: async (_t: Handoff, text: string) => { notes.push(text); } };
  const worker = await Worker.create({ connection: env.nativeConnection, taskQueue: "t", workflowsPath, activities });
  const result = await worker.runUntil(async () => {
    const h = await env.client.workflow.start(ticketToPr, { taskQueue: "t", workflowId: "nova:RH-1", args: [handoff] });
    await env.sleep("25 hours"); // skips a day of waiting
    await h.signal(decidePlan, { kind: "approve", by: "dana@example.com", version: "v1" });
    return h.result();
  });
  assert.equal(result, "https://github.com/RhinoHealth/fcp/pull/1");
  assert.equal(notes.length, 1); // reminded once, never parked
});

// ai-agents/orchestrator/test/recovery.test.ts (sketch): a VM dies once; recovery takes a fresh one
import { ApplicationFailure } from "@temporalio/common";

test("a lost VM is replaced and the run finishes", async () => {
  const acquired: string[] = [];
  let attempts = 0;
  const activities = {
    ...happyPath, // mocks for freshenSandbox, notify, releaseSandbox ...
    acquireSandbox: async () => { acquired.push(`vm-${acquired.length + 1}`); return { id: acquired.at(-1)! }; },
    workInSandbox: async () => {
      attempts += 1;
      if (attempts === 1) throw ApplicationFailure.create({ type: "SandboxDead", nonRetryable: true });
      return { needsAnswer: false, prUrl: "https://github.com/RhinoHealth/fcp/pull/1" };
    },
  };
  const worker = await Worker.create({ connection: env.nativeConnection, taskQueue: "t", workflowsPath, activities });
  await worker.runUntil(env.client.workflow.execute(ticketToPr, { taskQueue: "t", workflowId: "nova:RH-2", args: [handoff] }));
  assert.deepEqual(acquired, ["vm-1", "vm-2"]); // the dead VM was not reused
});

// ~/temporal-lab/test/replay.test.ts: the same shape as G3-29's orchestrator/test/replay.test.ts
import { test } from "node:test";
import { readdir, readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { Worker } from "@temporalio/worker";

test("saved workflow histories still replay", async () => {
  const workflowsPath = fileURLToPath(new URL("../src/workflows.ts", import.meta.url));
  const dir = new URL("./histories/", import.meta.url); // next to this file: npm test runs from the repo root
  for (const file of (await readdir(dir)).filter((f) => f.endsWith(".json")).sort()) {
    const history = JSON.parse(await readFile(new URL(file, dir), "utf8"));
    await Worker.runReplayHistory({ workflowsPath }, history, file);
  }
});
